    return typeof candidate.id === 'string'
        && candidate.id.trim().length > 0
        && typeof candidate.skill === 'string'
        && candidate.skill.trim().length > 0
        && typeof candidate.summary === 'string'
        && candidate.summary.trim().length > 0
